// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CameraJob) predicate.CameraJob {
	return predicate.CameraJob(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CameraJob) predicate.CameraJob {
	return predicate.CameraJob(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CameraJob) predicate.CameraJob {
	return predicate.CameraJob(sql.NotPredicates(p))
}
